contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint value) public payable {
        // owner check: msg.sender is the test contract, which deployed c
        require(msg.sender == c.owner(), "caller is owner");
        // fund c with enough Ether so that sends succeed unless value is huge
        // send more than any reasonable test value
        require(address(this).balance >= value + 1, "not enough balance");
        // top-level setup call: send Ether into c via its receive
        (bool ok, ) = address(c).call{value: value + 1}("");
        require(ok, "funding failed");
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule about sendMoney when caller is owner:
        // it must not revert when the target is a non-zero EOA (or any address that accepts Ether),
        // and if it completes, the contract's balance decreases by exactly value.
        // We avoid asserting about targets that could reject (contracts), so we restrict to EOAs
        // by requiring target has no code (EOA) in our precondition.
        require(target != address(0) && target.code.length == 0, "target must be a non-zero EOA");
        assert(!reverted && address(c).balance == balanceBefore - value);
    }

    receive() external payable {}
}

